import{_ as e,a as d,o,ai as a}from"./chunks/framework.BbOtTPsL.js";const m=JSON.parse(`{"title":"Products","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-catalog-products-list","title":"List Products (datagrid)","description":"The full Catalog → Products datagrid. Paginated { data, meta } envelope. Heavy relation blocks and a few EAV-derived fields are null on the listing (detail-only).","query":"curl -X GET \\"https://your-domain.com/api/admin/catalog/products?per_page=2&sort=id&order=asc\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/json\\"\\n","response":"{\\n  \\"data\\": [\\n    {\\n      \\"id\\": 1,\\n      \\"sku\\": \\"COASTALBREEZEMENSHOODIE\\",\\n      \\"name\\": \\"Coastal Breeze Men's Blue Zipper Hoodie\\",\\n      \\"type\\": \\"simple\\",\\n      \\"status\\": 1,\\n      \\"price\\": \\"100.0000\\",\\n      \\"formattedPrice\\": \\"$100.00\\",\\n      \\"specialPrice\\": null,\\n      \\"formattedSpecialPrice\\": null,\\n      \\"specialPriceFrom\\": null,\\n      \\"specialPriceTo\\": null,\\n      \\"quantity\\": 10000,\\n      \\"baseImageUrl\\": \\"http://localhost:8000/storage/product/1/zKcWZTLDjcawJmaNg8g1cpARqwVONgEKEflabstT.webp\\",\\n      \\"imagesCount\\": 1,\\n      \\"categoryId\\": 22,\\n      \\"categoryName\\": \\"Fashion\\",\\n      \\"channel\\": \\"default\\",\\n      \\"locale\\": \\"en\\",\\n      \\"attributeFamilyId\\": 1,\\n      \\"attributeFamilyName\\": \\"Default\\",\\n      \\"urlKey\\": \\"coastal-breeze-mens-blue-zipper-hoodie\\",\\n      \\"visibleIndividually\\": true,\\n      \\"shortDescription\\": \\"Stay warm and stylish with the Coastal Breeze Men's Blue Zipper Hoodie...\\",\\n      \\"description\\": \\"The Coastal Breeze Men's Blue Zipper Hoodie is your reliable companion...\\",\\n      \\"metaTitle\\": \\"Coastal Breeze Men's Blue Zipper Hoodie\\",\\n      \\"metaDescription\\": \\"Stay warm and stylish with the Coastal Breeze Men's Blue Zipper Hoodie...\\",\\n      \\"metaKeywords\\": \\"\\",\\n      \\"weight\\": 1,\\n      \\"featured\\": true,\\n      \\"new\\": true,\\n      \\"createdAt\\": \\"2024-04-16 17:32:38\\",\\n      \\"updatedAt\\": \\"2026-04-07 15:20:30\\",\\n      \\"taxCategoryId\\": null,\\n      \\"manageStock\\": null,\\n      \\"inStock\\": null,\\n      \\"translations\\": null,\\n      \\"images\\": null,\\n      \\"categories\\": null,\\n      \\"inventories\\": null,\\n      \\"customerGroupPrices\\": null,\\n      \\"superAttributes\\": null,\\n      \\"variants\\": null,\\n      \\"bundleOptions\\": null,\\n      \\"linkedProducts\\": null,\\n      \\"downloadableLinks\\": null,\\n      \\"downloadableSamples\\": null\\n    },\\n    {\\n      \\"id\\": 22,\\n      \\"sku\\": \\"bagistoNGRY3424234KJCKJK\\",\\n      \\"name\\": \\"Acme Drawstring Bag\\",\\n      \\"type\\": \\"bundle\\",\\n      \\"status\\": 1,\\n      \\"price\\": \\"3000.0000\\",\\n      \\"formattedPrice\\": \\"$3,000.00\\",\\n      \\"specialPrice\\": \\"2700.0000\\",\\n      \\"formattedSpecialPrice\\": \\"$2,700.00\\",\\n      \\"specialPriceFrom\\": null,\\n      \\"specialPriceTo\\": null,\\n      \\"quantity\\": 0,\\n      \\"baseImageUrl\\": null,\\n      \\"imagesCount\\": 0,\\n      \\"categoryId\\": null,\\n      \\"categoryName\\": null,\\n      \\"channel\\": \\"default\\",\\n      \\"locale\\": \\"en\\",\\n      \\"attributeFamilyId\\": 1,\\n      \\"attributeFamilyName\\": \\"Default\\",\\n      \\"urlKey\\": \\"acme-drawstring-bag\\",\\n      \\"visibleIndividually\\": true,\\n      \\"featured\\": false,\\n      \\"new\\": false,\\n      \\"createdAt\\": \\"2024-04-16 17:32:38\\",\\n      \\"updatedAt\\": \\"2026-04-07 15:20:30\\"\\n    }\\n  ],\\n  \\"meta\\": {\\n    \\"currentPage\\": 1,\\n    \\"perPage\\": 2,\\n    \\"lastPage\\": 151,\\n    \\"total\\": 302,\\n    \\"from\\": 1,\\n    \\"to\\": 2\\n  }\\n}\\n"},{"id":"admin-catalog-products-list-filtered","title":"List Products (AND-combined filters)","description":"Filters are AND-combined — more filters narrow the result. Here only active simple products of attribute family 1 within a price band are returned.","query":"curl -X GET \\"https://your-domain.com/api/admin/catalog/products?status=1&type=simple&attribute_family=1&price_from=50&price_to=200&sort=price&order=asc&per_page=10\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/json\\"\\n","response":"{\\n  \\"data\\": [\\n    {\\n      \\"id\\": 1,\\n      \\"sku\\": \\"COASTALBREEZEMENSHOODIE\\",\\n      \\"name\\": \\"Coastal Breeze Men's Blue Zipper Hoodie\\",\\n      \\"type\\": \\"simple\\",\\n      \\"status\\": 1,\\n      \\"price\\": \\"100.0000\\",\\n      \\"formattedPrice\\": \\"$100.00\\",\\n      \\"specialPrice\\": null,\\n      \\"formattedSpecialPrice\\": null,\\n      \\"quantity\\": 10000,\\n      \\"attributeFamilyId\\": 1,\\n      \\"attributeFamilyName\\": \\"Default\\"\\n    }\\n  ],\\n  \\"meta\\": { \\"currentPage\\": 1, \\"perPage\\": 10, \\"lastPage\\": 1, \\"total\\": 1, \\"from\\": 1, \\"to\\": 1 }\\n}\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/catalog/products/index.md","filePath":"api/rest-api/admin/catalog/products/index.md","lastUpdated":1781099665000}`),r={name:"api/rest-api/admin/catalog/products/index.md"};function i(c,t,n,s,l,p){return o(),d("div",null,t[0]||(t[0]=[a('<h1 id="products" tabindex="-1">Products <a class="header-anchor" href="#products" aria-label="Permalink to &quot;Products&quot;">​</a></h1><p>The Products menu is the catalog&#39;s product-management surface — list, search, create, edit, copy, and delete products, plus manage each product&#39;s images, per-source inventory, and customer-group prices. It mirrors the admin <strong>Catalog → Products</strong> screen.</p><h2 id="product-types" tabindex="-1">Product types <a class="header-anchor" href="#product-types" aria-label="Permalink to &quot;Product types&quot;">​</a></h2><p>Every product has a <code>type</code>, fixed at creation. There are seven:</p><table tabindex="0"><thead><tr><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>simple</code></td><td>A standalone product with its own price and stock.</td></tr><tr><td><code>virtual</code></td><td>Like simple but non-shippable (no weight/dimensions) — services, memberships.</td></tr><tr><td><code>downloadable</code></td><td>Sells downloadable <strong>links</strong> (paid files) and <strong>samples</strong> (free previews); non-stockable.</td></tr><tr><td><code>grouped</code></td><td>A storefront grouping of other simple products (<strong>linked products</strong>); has no own price.</td></tr><tr><td><code>bundle</code></td><td>A configurable kit built from <strong>bundle options</strong>; its price is calculated from the chosen items.</td></tr><tr><td><code>configurable</code></td><td>A parent with <strong>variants</strong> generated from variant-defining attributes (<code>super_attributes</code>, e.g. colour × size). Each variant is its own SKU with its own price/stock.</td></tr><tr><td><code>booking</code></td><td>A bookable product (default / appointment / event / rental / table sub-types) with time slots; non-stockable.</td></tr></tbody></table><p><strong>Composite types own no price or stock of their own.</strong> For <code>configurable</code>, <code>bundle</code>, <code>grouped</code>, and <code>booking</code>, the price and inventory live on the children — the variants, bundle items, linked products, or slots. Their top-level <code>price</code> / <code>quantity</code> are derived or empty.</p><h2 id="creating-a-product-is-two-steps" tabindex="-1">Creating a product is two steps <a class="header-anchor" href="#creating-a-product-is-two-steps" aria-label="Permalink to &quot;Creating a product is two steps&quot;">​</a></h2><p>Creation is deliberately minimal: a <code>POST</code> creates the shell from just <code>sku</code> + <code>attribute_family_id</code> + <code>type</code> (plus <code>super_attributes</code> for <code>configurable</code>). Everything else — name, description, price, images, categories, channels, inventory — is filled in afterwards via the <strong>update</strong> endpoint. This mirrors the admin&#39;s create-then-edit wizard.</p><h2 id="status-vs-visibleindividually" tabindex="-1"><code>status</code> vs <code>visibleIndividually</code> <a class="header-anchor" href="#status-vs-visibleindividually" aria-label="Permalink to &quot;`status` vs `visibleIndividually`&quot;">​</a></h2><p>Two independent flags control storefront presence:</p><ul><li><strong><code>status</code></strong> — <code>1</code> enabled / <code>0</code> disabled. A disabled product is fully hidden from the storefront.</li><li><strong><code>visibleIndividually</code></strong> — whether the product appears in category/search listings. Variant products and grouped-component products are usually set to <code>0</code> (reachable only through their parent), while still being <code>status = 1</code>.</li></ul><p>Both must effectively be on for a product to be browsable on its own. (<code>status</code> is stored on the flattened product table, resolved per channel + locale.)</p><h2 id="per-product-sub-resources" tabindex="-1">Per-product sub-resources <a class="header-anchor" href="#per-product-sub-resources" aria-label="Permalink to &quot;Per-product sub-resources&quot;">​</a></h2><p>The product edit screen&#39;s tabs map to their own endpoint groups, each scoped to one product:</p><ul><li><strong>Images</strong> — upload, reorder, and delete a product&#39;s images.</li><li><strong>Inventories</strong> — read and bulk-update the per-inventory-source stock quantities.</li><li><strong>Customer-group prices</strong> — tiered prices that apply to specific customer groups.</li></ul><p>These are not returned in full on the listing (they&#39;re detail-only); the single-product endpoint embeds them inline.</p><h2 id="the-product-listing" tabindex="-1">The product listing <a class="header-anchor" href="#the-product-listing" aria-label="Permalink to &quot;The product listing&quot;">​</a></h2><p><code>GET /api/admin/catalog/products</code> is the datagrid — a paginated <code>{ data, meta }</code> envelope.</p><h3 id="listing-filters-and-combined" tabindex="-1">Listing filters (AND-combined) <a class="header-anchor" href="#listing-filters-and-combined" aria-label="Permalink to &quot;Listing filters (AND-combined)&quot;">​</a></h3><p>All filters are <strong>combined with AND</strong> — every filter you add <strong>narrows</strong> the result set further. Pass them as query parameters:</p><table tabindex="0"><thead><tr><th>Filter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>channel</code></td><td>string</td><td>Channel code used to resolve per-channel values.</td></tr><tr><td><code>name</code></td><td>string</td><td>Partial product-name match.</td></tr><tr><td><code>sku</code></td><td>string</td><td>Partial SKU match.</td></tr><tr><td><code>attribute_family</code></td><td>integer</td><td>Attribute-family ID.</td></tr><tr><td><code>price_from</code> / <code>price_to</code></td><td>number</td><td>Price band (inclusive). <code>price=50,200</code> is shorthand for <code>price_from=50&amp;price_to=200</code>.</td></tr><tr><td><code>product_id</code></td><td>string</td><td>A single ID, or a comma-separated list (e.g. <code>1,22,2705</code>).</td></tr><tr><td><code>status</code></td><td>integer</td><td><code>0</code> (disabled) or <code>1</code> (active).</td></tr><tr><td><code>type</code></td><td>string</td><td>One of the seven product types.</td></tr><tr><td><code>locale</code></td><td>string</td><td>Locale code used to resolve translated values.</td></tr></tbody></table><p>Plus pagination and sort:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>page</code></td><td>integer</td><td>1-based page number (default <code>1</code>).</td></tr><tr><td><code>per_page</code></td><td>integer</td><td>Page size (default <code>10</code>, max <code>50</code>).</td></tr><tr><td><code>sort</code></td><td>string</td><td><code>product_id</code> (default), <code>sku</code>, <code>name</code>, <code>type</code>, <code>status</code>, <code>price</code>, <code>quantity</code>, <code>attribute_family</code>, <code>channel</code>.</td></tr><tr><td><code>order</code></td><td>string</td><td><code>asc</code> or <code>desc</code> (default <code>desc</code>).</td></tr></tbody></table><h3 id="listing-columns" tabindex="-1">Listing columns <a class="header-anchor" href="#listing-columns" aria-label="Permalink to &quot;Listing columns&quot;">​</a></h3><p>Every row carries these scalar columns. <strong>Heavy fields are <code>null</code> on the listing</strong> (fetch them from the <a href="/api/rest-api/admin/catalog/products/products-detail.html">detail endpoint</a>):</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Product ID.</td></tr><tr><td><code>sku</code></td><td>string</td><td>SKU.</td></tr><tr><td><code>name</code></td><td>string|null</td><td>Resolved for the active locale/channel. <code>null</code> for draft products with no name yet.</td></tr><tr><td><code>type</code></td><td>string</td><td>Product type.</td></tr><tr><td><code>status</code></td><td>integer</td><td><code>1</code> active / <code>0</code> disabled.</td></tr><tr><td><code>price</code></td><td>string|null</td><td>Base price (composite types carry no own price → <code>null</code>).</td></tr><tr><td><code>formattedPrice</code></td><td>string|null</td><td>Locale-formatted base price.</td></tr><tr><td><code>specialPrice</code></td><td>string|null</td><td>Discounted price, when a special price is set.</td></tr><tr><td><code>formattedSpecialPrice</code></td><td>string|null</td><td>Locale-formatted special price.</td></tr><tr><td><code>specialPriceFrom</code></td><td>string|null</td><td>Start date of the special-price window (<code>null</code> = always on).</td></tr><tr><td><code>specialPriceTo</code></td><td>string|null</td><td>End date of the special-price window (<code>null</code> = no end).</td></tr><tr><td><code>quantity</code></td><td>integer</td><td>Total stock across inventory sources.</td></tr><tr><td><code>baseImageUrl</code></td><td>string|null</td><td>Medium-cache base image URL.</td></tr><tr><td><code>imagesCount</code></td><td>integer</td><td>Number of images.</td></tr><tr><td><code>categoryId</code></td><td>integer|null</td><td>Primary category ID.</td></tr><tr><td><code>categoryName</code></td><td>string|null</td><td>Primary category name.</td></tr><tr><td><code>channel</code></td><td>string</td><td>Resolved channel code.</td></tr><tr><td><code>locale</code></td><td>string</td><td>Resolved locale code.</td></tr><tr><td><code>attributeFamilyId</code></td><td>integer</td><td>Attribute-family ID.</td></tr><tr><td><code>attributeFamilyName</code></td><td>string</td><td>Attribute-family name.</td></tr><tr><td><code>urlKey</code></td><td>string|null</td><td>Storefront URL slug.</td></tr><tr><td><code>visibleIndividually</code></td><td>boolean</td><td>Appears in category/search listings.</td></tr><tr><td><code>shortDescription</code> / <code>description</code></td><td>string|null</td><td>Resolved content.</td></tr><tr><td><code>metaTitle</code> / <code>metaDescription</code> / <code>metaKeywords</code></td><td>string|null</td><td>SEO fields.</td></tr><tr><td><code>weight</code></td><td>number|null</td><td>Product weight.</td></tr><tr><td><code>featured</code></td><td>boolean</td><td>Featured flag.</td></tr><tr><td><code>new</code></td><td>boolean</td><td>&quot;New&quot; flag.</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td>string</td><td>Timestamps.</td></tr><tr><td><code>taxCategoryId</code></td><td>integer|null</td><td><strong>Detail-only</strong> — <code>null</code> on the listing.</td></tr><tr><td><code>manageStock</code></td><td>boolean|null</td><td><strong>Detail-only</strong> — <code>null</code> on the listing.</td></tr><tr><td><code>inStock</code></td><td>boolean|null</td><td><strong>Detail-only</strong> — <code>null</code> on the listing.</td></tr><tr><td><code>translations</code>, <code>images</code>, <code>categories</code>, <code>inventories</code>, <code>customerGroupPrices</code>, <code>superAttributes</code>, <code>variants</code>, <code>bundleOptions</code>, <code>linkedProducts</code>, <code>downloadableLinks</code>, <code>downloadableSamples</code></td><td>array|null</td><td>Relation blocks — <strong>all <code>null</code> on the listing</strong>; populated only on the <a href="/api/rest-api/admin/catalog/products/products-detail.html">detail endpoint</a>.</td></tr></tbody></table><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>What it does</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/catalog/products/copy.html">Copy</a></td><td>Duplicates an existing product into a new <strong>draft</strong> product (a fresh SKU is generated).</td></tr><tr><td><a href="/api/rest-api/admin/catalog/products/mass-delete.html">Mass delete</a></td><td>Deletes several products at once — body <code>{ &quot;indices&quot;: [1, 22] }</code>. Missing IDs are skipped.</td></tr><tr><td><a href="/api/rest-api/admin/catalog/products/mass-update-status.html">Mass update status</a></td><td>Bulk enable/disable — body <code>{ &quot;indices&quot;: [1, 22], &quot;value&quot;: 0 }</code> (<code>0</code> = disable, <code>1</code> = active).</td></tr><tr><td><a href="/api/rest-api/admin/catalog/products/export.html">Export (CSV)</a></td><td>Downloads the listing as a CSV file, honouring the current filters; exports <strong>every matching row</strong>, not just the page. REST only.</td></tr></tbody></table><h2 id="endpoints-in-this-menu" tabindex="-1">Endpoints in this menu <a class="header-anchor" href="#endpoints-in-this-menu" aria-label="Permalink to &quot;Endpoints in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/catalog/products.html">List products</a></td><td><code>GET /api/admin/catalog/products</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/products/products-detail.html">Product detail</a></td><td><code>GET /api/admin/catalog/products/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/products/create.html">Create product</a></td><td><code>POST /api/admin/catalog/products</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/products/update.html">Update product</a></td><td><code>PUT /api/admin/catalog/products/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/products/delete.html">Delete product</a></td><td><code>DELETE /api/admin/catalog/products/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/products/copy.html">Copy product</a></td><td><code>POST /api/admin/catalog/products/{id}/copy</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/products/mass-delete.html">Mass delete</a></td><td><code>POST /api/admin/catalog/products/mass-delete</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/products/mass-update-status.html">Mass update status</a></td><td><code>POST /api/admin/catalog/products/mass-update-status</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/products/export.html">Export products (CSV)</a></td><td><code>GET /api/admin/catalog/products/export</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/products/images-upload.html">Upload images</a></td><td><code>POST /api/admin/catalog/products/{id}/images</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/products/images-reorder.html">Reorder images</a></td><td><code>PUT /api/admin/catalog/products/{id}/images/reorder</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/products/images-delete.html">Delete image</a></td><td><code>DELETE /api/admin/catalog/products/{id}/images/{imageId}</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/products/inventories-list.html">List inventories</a></td><td><code>GET /api/admin/catalog/products/{id}/inventories</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/products/inventories-update.html">Update inventories</a></td><td><code>PUT /api/admin/catalog/products/{id}/inventories</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/products/customer-group-prices-list.html">List customer-group prices</a></td><td><code>GET /api/admin/catalog/products/{id}/customer-group-prices</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/products/customer-group-prices-create.html">Add customer-group price</a></td><td><code>POST /api/admin/catalog/products/{id}/customer-group-prices</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/products/customer-group-prices-update.html">Update customer-group price</a></td><td><code>PUT /api/admin/catalog/products/{id}/customer-group-prices/{priceId}</code></td></tr><tr><td><a href="/api/rest-api/admin/catalog/products/customer-group-prices-delete.html">Delete customer-group price</a></td><td><code>DELETE /api/admin/catalog/products/{id}/customer-group-prices/{priceId}</code></td></tr></tbody></table><p>The canonical product listing is <a href="/api/rest-api/admin/catalog/products.html">List products</a> (<code>GET /api/admin/catalog/products</code>) above. There is also a separate slim <a href="/api/rest-api/admin/catalog/products/list.html">Add-Product Search</a> (<code>GET /api/admin/products</code>) used only by the Create-Order &quot;Add Product&quot; modal — not the product listing.</p><p>All Products endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>. Reads require <code>catalog.products.view</code>; writes require the matching <code>catalog.products.create</code> / <code>.edit</code> / <code>.delete</code> permission.</p>',32)]))}const g=e(r,[["render",i]]);export{m as __pageData,g as default};
